      en: ["Windmill hill", "View over the coast", "Sandy moraine soil", "Elevation 45 meters"],
      es: ["Colina de los molinos de viento", "Vistas sobre la costa", "Suelo de morrena arenosa", "Altura 45 metros"],
      pt: ["Colina dos moinhos de vento", "Vista sobre a costa", "Solo de moreia arenosa", "Altura 45 metros"],
